INSERT INTO site_settings(id,email,phone,whatsapp,city,about) VALUES(1,'','','','','A Escolha Certa aproxima famílias e profissionais do cuidado. Nosso propósito é acolher cada necessidade com atenção, respeito e responsabilidade. Converse com nossa equipe para conhecer o atendimento disponível na sua região.');
INSERT INTO contents(kind,title,summary,body,published,sort_order,created_at) VALUES
('SERVICE','Cuidado com idosos','Presença, atenção e apoio à rotina, respeitando a autonomia de cada pessoa.','Apoio nas atividades do dia a dia e companhia. O planejamento considera as necessidades da família e os limites de atuação do cuidador. Solicite uma avaliação para definir horários e perfil profissional.',true,1,CURRENT_TIMESTAMP),
('SERVICE','Cuidado com crianças','Acolhimento e acompanhamento para uma rotina mais tranquila.','Acompanhamento e apoio à rotina infantil, com atenção às orientações da família. Converse com nossa equipe sobre idade, horários e necessidades.',true,2,CURRENT_TIMESTAMP),
('SERVICE','Apoio à pessoa com deficiência','Cuidado individualizado, com respeito à autonomia e à inclusão.','Acompanhamento planejado com a família, considerando as necessidades e preferências da pessoa assistida.',true,3,CURRENT_TIMESTAMP),
('SERVICE','Companhia e apoio diário','Uma presença cuidadosa em diferentes momentos da vida.','Companhia e apoio às atividades cotidianas. A disponibilidade e o escopo são definidos após o primeiro contato.',true,4,CURRENT_TIMESTAMP),
('POST','Como se preparar para conversar com um cuidador','Organizar as necessidades da rotina ajuda a encontrar um atendimento adequado.','Antes do primeiro contato, anote os horários desejados, as atividades que precisam de apoio e as preferências da pessoa assistida.
